        pageToken = (resp && resp.nextPageToken) || '';
        if (!pageToken) break;
        await __tick('Litterature grise : ClinicalTrials.gov… (' + got + ' essais)');
      }
      console.log('[ClinicalTrials] ' + got + ' essais recus (' + page + ' page(s)' + (NOLIM ? ', sans limite' : '') + ')');
    } catch (e) { __echecCT = true; console.log('[ClinicalTrials] erreur fetch : ' + (e && e.message ? e.message : e)); }
    // LA FICHE RECOIT LE PLAFOND QUI A BORNE LA LECTURE, case « sans limite » comprise
    // (2026-09-12) : sans limite, `cap` vaut le plafond de securite. La fiche recevait 0, et
    // 10 000 essais lus sur 150 000 annonces se disaient « ecart inexplique ».
    __ficheEcart('clinicaltrials', __annonce, got, cap, __echecCT, __pageCT);
  }
}

// === Europe PMC (REST gratuit sans cle ; preprints si SRC:PPR) - pagination cursorMark ===
if (data.enable_europepmc === true) {
  // SEARCH_DERIVE_v1 : EPMC supporte la troncature * et les phrases -> NE PAS passer
  // par clean() (qui strippe *?~) ; collapse des espaces seulement. Requete derivee.
  var epq = (data.europepmc_query || data.openalex_query || data.question || '').toString().replace(/\s+/g,' ').trim();
  if (epq) {
    await __tick('Litterature grise : Europe PMC…');
    if (dY1 || dY2) { epq = '(' + epq + ') AND (PUB_YEAR:[' + (dY1 || 0) + ' TO ' + (dY2 || 3000) + '])'; }
    const cap = __capOf(data.cap_europepmc);
    let got = 0; let cursor = '*'; let page = 0; var __annonceEp = 0; let __echecEP = false; let __pageEP = false;
    try {
      while (got < cap) {
        const pageSize = Math.min(cap - got, 1000);
        const url = 'https://www.ebi.ac.uk/europepmc/webservices/rest/search?format=json&resultType=core&pageSize=' + pageSize + '&cursorMark=' + encodeURIComponent(cursor) + '&query=' + encodeURIComponent(epq);
        // Meme regle que ClinicalTrials.gov, plus haut (2026-09-12).
        let resp;
        try { resp = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'UltraLab-SystematicReview/1.0', 'Accept': 'application/json' }, timeout: 60000, json: true }); }
        catch (e) { if (!got) throw e; __pageEP = true; console.log('[EuropePMC] page perdue : ' + (e && e.message ? e.message : e)); break; }
        // `hitCount` arrive dans CHAQUE reponse et n'etait simplement pas lu.
        if (page === 0 && resp && typeof resp.hitCount === 'number') __annonceEp = resp.hitCount;
        const hits = ((resp && resp.resultList && resp.resultList.result) || []);
        if (!hits.length) break;
        for (let i = 0; i < hits.length && got < cap; i++) {
          const r = hits[i];
          if (!r.title) continue;
          const isPPR = (r.source === 'PPR');
          const auth = (r.authorString || '').split(',').map(function(x){ return x.trim(); }).filter(Boolean).slice(0, 25);
          const jt = (r.journalInfo && r.journalInfo.journal && r.journalInfo.journal.title) || (isPPR ? 'Preprint (Europe PMC)' : 'Europe PMC');
          articles.push({ title: r.title, abstract: r.abstractText || '', authors: auth, year: String(r.pubYear || ''), doi: r.doi || '', pmid: r.pmid || '', issn: '', journal: jt, url: 'https://europepmc.org/article/' + (r.source || 'MED') + '/' + (r.id || ''), publication_type: isPPR ? 'Preprint' : '', source: 'europepmc', _source: 'europepmc' });
          got++;
        }
        page++;
        const next = (resp && resp.nextCursorMark) || '';
        if (!next || next === cursor) break;
        cursor = next;
        await __tick('Litterature grise : Europe PMC… (' + got + ' resultats)');
      }
      console.log('[EuropePMC] ' + got + ' resultats recus (' + page + ' page(s)' + (NOLIM ? ', sans limite' : '') + ')');
    } catch (e) { __echecEP = true; console.log('[EuropePMC] erreur fetch : ' + (e && e.message ? e.message : e)); }
    // La fiche recoit le plafond qui a borne la lecture, comme celle de ClinicalTrials.gov.
    __ficheEcart('europepmc', __annonceEp, got, cap, __echecEP, __pageEP);
  }
}

// === ISRCTN (registre d'essais ; XML format OMS parse par decoupage de chaine, sans regex) ===
if (data.enable_isrctn === true) {
  const iq = clean(data.isrctn_query || data.question || data.openalex_query);
  if (iq) {
    await __tick('Litterature grise : ISRCTN…');
    const cap = __capOf(data.cap_isrctn);
    var __isrctnRecu = 0;
    let __echecIS = false;
    const url = 'https://www.isrctn.com/api/query/format/who?limit=' + Math.min(cap, SAFETY) + '&q=' + encodeURIComponent(iq);
    try {
      const xml = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'UltraLab-SystematicReview/1.0' }, timeout: 90000 });
      const tag = function(blk, t) {
        const a = blk.indexOf('<' + t + '>'); if (a < 0) return '';
        const b = blk.indexOf('</' + t + '>', a); if (b < 0) return '';
        return blk.slice(a + t.length + 2, b).split('<![CDATA[').join('').split(']]>').join('').trim();
      };
      const blocks = String(xml).split('<trial>').slice(1);
      // CE REGISTRE N'ANNONCE PAS DE TOTAL dans le format demande : on rend une fiche
      // avec un total INCONNU (zero), ce que la reconciliation range dans
      // `bases_sans_total_annonce`. Inventer un total serait pire que ne rien dire.
      __isrctnRecu = blocks.length;
      console.log('[ISRCTN] ' + blocks.length + ' essais recus' + (NOLIM ? ' (sans limite)' : ''));
      for (let i = 0; i < Math.min(blocks.length, cap); i++) {
        const blk = blocks[i];
        const title = tag(blk, 'public_title') || tag(blk, 'scientific_title');
        if (!title) continue;
        const tid = tag(blk, 'trial_id') || tag(blk, 'utrn');
        const dreg = tag(blk, 'date_registration');
        var y = '';
        const parts = dreg.split(/[^0-9]/).filter(function(x){ return x.length === 4; });
        if (parts.length) y = parts[0];
        // RESUME ENTIER (2026-09-11). Ce resume assemble titre scientifique, intervention et
        // criteres d'inclusion. La coupe a 2 000 caracteres faisait tomber la FIN des criteres, ce
        // que le tri lit pour trancher (mesure : 3 014 caracteres assembles, 2 000 rendus). La
        // branche ClinicalTrials.gov, plus haut, n'a jamais coupe le sien.
        // tests/test_resume_reconstruit_entier.py execute ce noeud.
        const abs = [tag(blk, 'scientific_title'), tag(blk, 'i_freetext'), tag(blk, 'inclusion_criteria')].filter(Boolean).join(', ');
        articles.push({ title: title, abstract: abs, authors: [], year: y, doi: '', pmid: '', issn: '', journal: 'ISRCTN registry', url: tag(blk, 'url') || (tid ? ('https://www.isrctn.com/' + tid) : ''), registry_id: tid, publication_type: 'Trial registration', source: 'isrctn', _source: 'isrctn' });
      }
    } catch (e) { __echecIS = true; console.log('[ISRCTN] erreur fetch : ' + (e && e.message ? e.message : e)); }
    __ficheEcart('isrctn', 0, __isrctnRecu, NOLIM ? 0 : cap, __echecIS);
  }
}

// LES FICHES PARTENT AVEC LES ARTICLES, exactement comme pour les huit autres sources :
// le noeud d'assemblage les separe sur `_diag` et n'en fait jamais des references.
return articles.map(function(a) { return { json: a }; })
  .concat(__diag.map(function(f) { return { json: f }; }));
